import{calculator,CalcError,has,pos,frac,nonneg,pick,ceilSafe,dflt,num,appliance}from './core.js?ver=c8a24342f7';const CHEMISTRIES=['tubular','lead_acid','agm','gel','lifepo4'];function dodFor(i,d){const chemistry=pick(i,'chemistry',CHEMISTRIES,'tubular');const def=chemistry==='lifepo4'?dflt(d,'dod_lifepo4'):dflt(d,'dod_lead_acid');return{chemistry,dod:frac(i,'dod',def)};}
function chargeEffFor(chemistry,i,d){const def=chemistry==='lifepo4'?dflt(d,'charge_eff_lifepo4'):dflt(d,'charge_eff_lead_acid');return frac(i,'charge_eff',def);}
function drawFor(i,d){const inverter_eff=frac(i,'inverter_eff',dflt(d,'inverter_eff_ups'));const load_w=pos(i,'load_w',undefined,'load_must_be_positive');if(load_w>dflt(d,'load_w_max'))throw new CalcError('load_w_too_large','load_w',dflt(d,'load_w_max'));const idle_w=inverter_eff<1?(has(i,'idle_w')?nonneg(i,'idle_w'):appliance(d,'ups-idle').running_w):0;return{inverter_eff,load_w,idle_w,battery_w:load_w/inverter_eff+idle_w};}
function currentFor(battery_w,volts,ah,chemistry,d){const battery_a=battery_w/volts;const c_rate=battery_a/ah;const max_c_rate=chemistry==='lifepo4'?dflt(d,'max_c_rate_lifepo4'):dflt(d,'max_c_rate_lead_acid');return{battery_a,cutoff_a:battery_a/dflt(d,'dc_cutoff_ratio'),c_rate,max_c_rate,high_c_rate:c_rate>max_c_rate+1e-9};}
export const battery_runtime=calculator((i,d)=>{const ah=pos(i,'ah');const volts=pos(i,'volts');const{chemistry,dod}=dodFor(i,d);const w=drawFor(i,d);const stored_wh=ah*volts*dod;const hours=stored_wh/w.battery_w;return{chemistry,ah,volts,dod,...w,stored_wh,hours,minutes:hours*60,...currentFor(w.battery_w,volts,ah,chemistry,d)};});
export const battery_bank=calculator((i,d)=>{const w=drawFor(i,d);const hours=pos(i,'hours');const volts=pos(i,'volts');const{chemistry,dod}=dodFor(i,d);const ah_required=(w.battery_w*hours)/(volts*dod);const out={chemistry,...w,hours,volts,dod,load_kwh:(w.load_w*hours)/1000,battery_kwh_draw:(w.battery_w*hours)/1000,ah_required,kwh_required:(ah_required*volts)/1000};if(has(i,'battery_ah')){const battery_ah=pos(i,'battery_ah');const battery_v=pos(i,'battery_v');const series=volts/battery_v;if(Math.abs(series-Math.round(series))>1e-9)throw new CalcError('bank_voltage_not_multiple_of_battery','battery_v');const strings=ceilSafe(ah_required/battery_ah);Object.assign(out,{battery_ah,battery_v,series:Math.round(series),strings,batteries:strings*Math.round(series)});}
return{...out,...currentFor(w.battery_w,volts,out.strings?out.strings*out.battery_ah:ah_required,chemistry,d)};});export const loadshedding=calculator((i,d)=>{const ah=pos(i,'ah');const{chemistry,dod}=dodFor(i,d);const charge_a=pos(i,'charge_a');const charge_eff=chargeEffFor(chemistry,i,d);const grid_hours_between=nonneg(i,'grid_hours_between');const recharge_hours=(ah*dod)/(charge_a*charge_eff);return{ah,dod,charge_a,charge_eff,grid_hours_between,recharge_hours,fully_recharged:recharge_hours<=grid_hours_between};});export const ups_capacity=calculator((i,d)=>{const va=pos(i,'va');const pf=frac(i,'pf',dflt(d,'pf_ups_line_interactive'));const load_w=pos(i,'load_w',undefined,'load_must_be_positive');const max_w=va*pf;let ok=load_w<=max_w;const out={va,pf,load_w,max_w,load_pct:(load_w/max_w)*100};if(has(i,'surge_w')||has(i,'surge_rating_w')){const surge_w=nonneg(i,'surge_w');const surge_rating_w=pos(i,'surge_rating_w');out.surge_ok=surge_w<=surge_rating_w;ok=ok&&out.surge_ok;}
out.can_run=ok;return out;});
export const ups_backup=calculator((i,d)=>{const cap=ups_capacity.raw(i,d);if(!cap.can_run)throw new CalcError(cap.surge_ok===false?'surge_exceeds_ups_rating':'load_exceeds_ups_rating','load_w');const run=battery_runtime.raw(i,d);return{...cap,...run};});export const series_parallel=calculator((i)=>{const n_series=num(i,'n_series',{min:1});const n_parallel=num(i,'n_parallel',{min:1});if(!Number.isInteger(n_series))throw new CalcError('n_series_must_be_whole','n_series');if(!Number.isInteger(n_parallel))throw new CalcError('n_parallel_must_be_whole','n_parallel');const v=pos(i,'v');const ah=pos(i,'ah');const v_total=n_series*v;const ah_total=n_parallel*ah;return{n_series,n_parallel,batteries:n_series*n_parallel,v_total,ah_total,kwh:(v_total*ah_total)/1000};});export const ebike=calculator((i,d)=>{const v=pos(i,'v');const ah=pos(i,'ah');const eta=frac(i,'eta',dflt(d,'ebike_charger_eff'));const tariff=nonneg(i,'tariff');const range_km=pos(i,'range_km');const kwh=(ah*v)/1000/eta;const rs_per_charge=kwh*tariff;return{v,ah,eta,tariff,range_km,kwh,rs_per_charge,rs_per_km:rs_per_charge/range_km};});
